from math import comb
from itertools import product
from typing import Iterator, Tuple

def weak_compositions(m: int, d: int) -> Iterator[Tuple[int, ...]]:
    if m == 0:
        if d == 0: yield ()
        return
    if m == 1:
        yield (d,); return
    for first in range(d + 1):
        for rest in weak_compositions(m - 1, d - first):
            yield (first,) + rest

def brute(m: int, a: int, d: int) -> int:
    total = 0
    for tup in weak_compositions(m, d):
        p = 1
        for i in tup: p *= comb(a + i, a)
        total += p
    return total

def closed(m: int, a: int, d: int) -> int:
    return comb(max(0, m*a + d + m - 1), d)

for m in range(5):
    for a in range(4):
        for d in range(7):
            assert brute(m, a, d) == closed(m, a, d), (m, a, d)
print("Identity verified for all m<5, a<4, d<7.")

from math import comb
from itertools import product
from typing import Sequence, Tuple, Iterator

def weak_compositions(m: int, d: int) -> Iterator[Tuple[int, ...]]:
    if m == 1:
        yield (d,); return
    for first in range(d + 1):
        for rest in weak_compositions(m - 1, d - first):
            yield (first,) + rest

def brute_hetero(a: Sequence[int], d: int) -> int:
    total = 0
    for tup in weak_compositions(len(a), d):
        p = 1
        for aj, ij in zip(a, tup): p *= comb(aj + ij, aj)
        total += p
    return total

def closed_hetero(a: Sequence[int], d: int) -> int:
    return comb(max(0, sum(a) + d + len(a) - 1), d)

# Any two parameter vectors with the same sum give the same value.
for d in range(6):
    v1 = brute_hetero((0, 1, 4), d)
    v2 = brute_hetero((2, 2, 1), d)
    assert v1 == v2 == closed_hetero((0,1,4), d)
    print(f"d={d}: (0,1,4) and (2,2,1) both give {v1}")

from math import comb

# The three-factor instance C(3a+d+2, d) as it appears when extending a Latin
# rectangle by one row. We tabulate the closed form against a small direct sum.
def three_factor_sum(a: int, d: int) -> int:
    s = 0
    for i1 in range(d + 1):
        for i2 in range(d - i1 + 1):
            i3 = d - i1 - i2
            s += comb(a+i1, a) * comb(a+i2, a) * comb(a+i3, a)
    return s

print("a  d   direct-sum   C(3a+d+2, d)")
for a in range(4):
    for d in range(5):
        print(f"{a}  {d}   {three_factor_sum(a,d):>9}   {comb(3*a+d+2, d):>9}")

