    return BINOMIAL(top, d)

function MULTICHOOSE(r, k):
    if r == 0: return (k == 0 ? 1 : 0)
    return BINOMIAL(r + k - 1, k)

function MULTICHOOSE_VANDERMONDE(r, t, d):
    return sum over k in 0..d of MULTICHOOSE(r,k) * MULTICHOOSE(t,d-k)

