from math import comb

def multichoose(r: int, k: int) -> int:
    """((r choose k)) = C(r+k-1, k), with boundary ((0,k)) = [k==0]."""
    if r == 0:
        return 1 if k == 0 else 0
    return comb(r + k - 1, k)

def multichoose_vandermonde(r: int, t: int, d: int) -> int:
    """Return sum_{k=0}^{d} ((r,k)) * ((t,d-k)); equals ((r+t,d)).

    This is the two-fold convolution that, applied once per inserted factor,
    drives the induction proving the full multinomial identity. O(d) terms.
    """
    return sum(multichoose(r, k) * multichoose(t, d - k) for k in range(d + 1))

